#include <vector>
#include <omp.h>
#include <algorithm>   // for std::min

/* Compute the reverse prefix (suffix) sum of the vector x into output.
   The result at position i is  sum_{j=i}^{n-1} x[j].
   The implementation works correctly for any number of OpenMP threads. */
void reversePrefixSum(const std::vector<int>& x, std::vector<int>& output)
{
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    // --------------------------------------------------------------------
    // 1) First parallel pass: each thread computes the sum of its own chunk.
    // --------------------------------------------------------------------
    int max_threads = omp_get_max_threads();
    int used_threads = std::min<int>(static_cast<int>(n), max_threads);

    std::vector<long long> blockSum(used_threads, 0);   // sum of each block

    #pragma omp parallel num_threads(used_threads)
    {
        int tid = omp_get_thread_num();
        int nt  = omp_get_num_threads();

        // Compute the range [first, last) for this thread (balanced partition)
        std::size_t chunk = n / nt;
        std::size_t remainder = n % nt;
        std::size_t first = tid * chunk + std::min<std::size_t>(tid, remainder);
        std::size_t last  = first + chunk + (tid < remainder ? 1 : 0); // one‑past

        long long local_sum = 0;
        for (std::size_t i = first; i < last; ++i)
            local_sum += static_cast<long long>(x[i]);

        blockSum[tid] = local_sum;          // store the block total
    }

    // --------------------------------------------------------------------
    // 2) Compute the suffix of block sums (the total of all blocks to the right).
    // --------------------------------------------------------------------
    std::vector<long long> suffixBlockSum(used_threads, 0);
    // suffixBlockSum[i] = sum of blockSum of blocks with index > i
    for (int i = used_threads - 2; i >= 0; --i)
        suffixBlockSum[i] = suffixBlockSum[i + 1] + blockSum[i + 1];

    // --------------------------------------------------------------------
    // 3) Second parallel pass: compute the suffix sum inside each block,
    //    adding the contribution of all blocks to its right.
    // --------------------------------------------------------------------
    #pragma omp parallel num_threads(used_threads)
    {
        int tid = omp_get_thread_num();
        int nt  = omp_get_num_threads();

        // Same partitioning as before
        std::size_t chunk = n / nt;
        std::size_t remainder = n % nt;
        std::size_t first = tid * chunk + std::min<std::size_t>(tid, remainder);
        std::size_t last  = first + chunk + (tid < remainder ? 1 : 0); // one‑past

        long long running = suffixBlockSum[tid];   // sum of all elements to the right of this block
        // Walk backwards inside the block to build the suffix sum
        for (std::size_t idx = last; idx-- > first; )
        {
            running += static_cast<long long>(x[idx]);
            output[idx] = static_cast<int>(running);
        }
    }
}
